import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';

test('exportCsv returns header line', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv ends with newline', () => {
  const result = exportCsv([]);
  assert.equal(result[result.length - 1], '\n');
});

test('exportCsv with single invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 },
      ],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.match(lines[1], /INV-2026-0001/);
  assert.match(lines[1], /Acme/);
  assert.match(lines[1], /100.00/);
});

test('exportCsv with multiple invoices', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-002',
      issueDate: '2026-10-08',
      dueDate: '2026-11-07',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 50000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.equal(lines.length, 4);
  assert.match(lines[1], /INV-2026-0001/);
  assert.match(lines[2], /INV-2026-0002/);
});

test('exportCsv formats amounts without currency sign', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 12345, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.match(lines[1], /123.45/);
  assert.notMatch(lines[1], /€/);
  assert.notMatch(lines[1], /\$/);
});

test('exportCsv formats amounts with 2 decimals', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10050, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  assert.match(result, /100.50/);
});

test('exportCsv uses dot as decimal separator', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10050, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  assert.match(result, /100\.50/);
  assert.notMatch(result, /100,50/);
});

test('exportCsv includes customer name', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  assert.match(result, /,Acme,/);
});

test('exportCsv with discount', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 20, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '100.00');
  assert.equal(fields[6], '20.00');
  assert.equal(fields[8], '80.00');
});

test('exportCsv with VAT', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '100.00');
  assert.equal(fields[7], '21.00');
  assert.equal(fields[8], '121.00');
});

test('exportCsv with discount and VAT', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 21 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '100.00');
  assert.equal(fields[6], '10.00');
  const vat = Math.round(90 * 21 / 100);
  assert.equal(fields[7], (vat / 100).toFixed(2));
});

test('exportCsv with payment', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'partially_paid',
      lines: [{ qty: 1, unitPrice: 50000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 20000, date: '2026-10-10' }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '500.00');
  assert.equal(fields[9], '300.00');
});

test('exportCsv escapes fields with commas', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.match(lines[1], /"[^"]*"/);
});

test('exportCsv escapes fields with double quotes', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-003',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  assert.match(result, /"[^"]*""/);
});

test('exportCsv with multiple lines per invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [
        { qty: 10, unitPrice: 5000, discountPercent: 0, vatRate: 21 },
        { qty: 5, unitPrice: 8000, discountPercent: 10, vatRate: 9 },
      ],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[0], 'INV-2026-0001');
  const subtotal = 50000 + 40000;
  const discount = Math.round(40000 * 10 / 100);
  assert.equal(fields[5], (subtotal / 100).toFixed(2));
  assert.equal(fields[6], (discount / 100).toFixed(2));
});

test('exportCsv maintains invoice order', () => {
  const invoices = [
    {
      number: 'INV-C',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-A',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-15',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-B',
      customerId: 'C-001',
      issueDate: '2026-10-05',
      dueDate: '2026-10-19',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.match(lines[1], /INV-C/);
  assert.match(lines[2], /INV-A/);
  assert.match(lines[3], /INV-B/);
});

test('exportCsv with empty invoice list', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  assert.equal(lines.length, 2);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[1], '');
});

test('exportCsv with paid invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'paid',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 10000, date: '2026-10-15' }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[4], 'paid');
  assert.equal(fields[9], '0.00');
});

test('exportCsv with draft invoice', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.match(lines[1], /,draft,/);
});

test('exportCsv with missing invoice number (draft)', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
