  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[0], 'undefined');
});

test('exportCsv with large amounts', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1000, unitPrice: 500000, discountPercent: 0, vatRate: 0 }],
