test('exportCsv with zero amounts', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 0, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  assert.match(result, /0.00/);
});

test('exportCsv preserves field order', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields.length, 10);
  assert.equal(fields[0], 'INV-2026-0001');
  assert.equal(fields[1], 'Acme');
  assert.equal(fields[2], '2026-10-07');
  assert.equal(fields[3], '2026-10-21');
  assert.equal(fields[4], 'issued');
  assert.equal(fields[5], '100.00');
  assert.equal(fields[6], '0.00');
  assert.equal(fields[7], '0.00');
  assert.equal(fields[8], '100.00');
  assert.equal(fields[9], '100.00');
});

test('exportCsv with customer having comma in name', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-003',
      issueDate: '2026-10-07',
      dueDate: '2026-10-21',
